import {validateWebsiteData} from '../../website-data.mjs';const origin='https://brownnoodyai-sketch.github.io';try{const r=await fetch(origin+'/website-data.json?probe='+Date.now(),{cache:'no-store',redirect:'error',signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('HTTP '+r.status);const d=validateWebsiteData(await r.json());console.log(JSON.stringify({websiteDataReachable:true,services:d.items.filter(i=>i.kind==='SERVICE'&&i.active).length,products:d.items.filter(i=>i.kind==='PRODUCT'&&i.active).length,coreApiDependency:false}));}catch(e){console.error(JSON.stringify({websiteDataReachable:false,error:e.message}));process.exitCode=1;}
